-- 0146: Frieren — Yorushikas „Haru“ wird 晴る geschrieben („aufklaren“), nicht 春 („Frühling“). Idempotent.
update question_translations set explanation = 'The title is written 晴る and means roughly “to clear up” – not “spring”.' where lang = 'en' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Welche Band singt „Haru“, das zweite Opening des Frieren-Anime?');
update question_translations set explanation = 'El título se escribe 晴る y significa más o menos «despejarse», no «primavera».' where lang = 'es' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Welche Band singt „Haru“, das zweite Opening des Frieren-Anime?');
update question_translations set explanation = 'Le titre s’écrit 晴る et signifie à peu près « s’éclaircir » – et non « printemps ».' where lang = 'fr' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Welche Band singt „Haru“, das zweite Opening des Frieren-Anime?');
update question_translations set explanation = 'O título é escrito 晴る e significa algo como “clarear” – não “primavera”.' where lang = 'pt' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Welche Band singt „Haru“, das zweite Opening des Frieren-Anime?');
update question_translations set explanation = 'Il titolo si scrive 晴る e significa all’incirca “rasserenarsi”, non “primavera”.' where lang = 'it' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Welche Band singt „Haru“, das zweite Opening des Frieren-Anime?');
update question_translations set explanation = 'Judulnya ditulis 晴る dan kira-kira berarti “menjadi cerah” – bukan “musim semi”.' where lang = 'id' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Welche Band singt „Haru“, das zweite Opening des Frieren-Anime?');
update question_translations set explanation = 'Başlık 晴る diye yazılır ve kabaca “açılmak, durulmak” anlamına gelir – “bahar” değil.' where lang = 'tr' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Welche Band singt „Haru“, das zweite Opening des Frieren-Anime?');
update question_translations set explanation = 'Tytuł zapisuje się 晴る i oznacza mniej więcej „przejaśniać się” – nie „wiosna”.' where lang = 'pl' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Welche Band singt „Haru“, das zweite Opening des Frieren-Anime?');
update question_translations set explanation = 'Tựa bài được viết là 晴る, nghĩa đại khái là “trời quang đãng” – không phải “mùa xuân”.' where lang = 'vi' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Welche Band singt „Haru“, das zweite Opening des Frieren-Anime?');
update question_translations set explanation = '曲名は「春」ではなく「晴る」と書きます。' where lang = 'ja' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Welche Band singt „Haru“, das zweite Opening des Frieren-Anime?');
update question_translations set explanation = '제목은 ‘봄(春)’이 아니라 ‘맑아지다’라는 뜻의 晴る로 써요.' where lang = 'ko' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Welche Band singt „Haru“, das zweite Opening des Frieren-Anime?');
update question_translations set explanation = 'ชื่อเพลงเขียนว่า 晴る หมายถึงประมาณ “ฟ้าเปิด” ไม่ใช่ “ฤดูใบไม้ผลิ”' where lang = 'th' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Welche Band singt „Haru“, das zweite Opening des Frieren-Anime?');
update question_translations set explanation = 'Название пишется 晴る и означает примерно «проясняться», а не «весна».' where lang = 'ru' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Welche Band singt „Haru“, das zweite Opening des Frieren-Anime?');
update question_translations set explanation = 'يُكتب العنوان 晴る ويعني تقريبًا «يصفو الجو»، وليس «الربيع».' where lang = 'ar' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Welche Band singt „Haru“, das zweite Opening des Frieren-Anime?');
update question_translations set explanation = 'Der Titel wird 晴る geschrieben und bedeutet etwa „aufklaren“ – nicht „Frühling“.' where lang = 'de' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Welche Band singt „Haru“, das zweite Opening des Frieren-Anime?');
